styl:
.iqbr-section-bordered--brad-full{border-radius:32px !important}
@media screen and (max-width: 600px){.iqbr-section-bordered--text-pad-small{padding-left:20px !important;padding-right:20px !important}}
.iqbr-section-bordered--pb44{padding-bottom:44px}
.iqbr-section-bordered--pt44{padding-top:44px}
.iqbr-title-middle--middle-title{font-family:Helvetica !important;font-style:normal;font-weight:700;font-size:32px;line-height:42px;color:#ececed}
@media screen and (max-width: 600px){.iqbr-title-middle--middle-title{font-size:26px !important;line-height:32px !important}}
.iqbr-title-middle--pb12{padding-bottom:12px !important}
.iqbr-text-gray--pb32{padding-bottom:32px}
.iqbr-text-gray--gray-text{font-family:Helvetica !important;font-style:normal;font-weight:400;font-size:18px;line-height:27px;color:#a6a6ab}
.iqbr-image--center{text-align:center;margin:0 auto}
.iqbr-two-columns--left-block{display:inline-block;vertical-align:top;width:234px;min-height:443px;background:#101314;border-radius:16px}
@media screen and (max-width: 600px){.iqbr-two-columns--left-block{float:none !important;display:block !important;width:100% !important;margin-bottom:20px !important}}
.iqbr-two-columns--padding-block{padding:24px}
.iqbr-two-columns--right-block{display:inline-block;vertical-align:top;width:234px;min-height:443px;background:#101314;border-radius:16px;float:right}
@media screen and (max-width: 600px){.iqbr-two-columns--right-block{float:none !important;display:block !important;width:100% !important}}
.iqbr-block-title--block-title{font-family:Helvetica !important;font-style:normal;font-weight:700;font-size:24px;line-height:31px;color:#ececed}
.iqbr-list-3--pb8{padding-bottom:8px}
.iqbr-list-3--block-text{font-family:Helvetica !important;font-style:normal;font-weight:400;font-size:18px;line-height:27px;color:#ececed}
.iqbr-button--w280{width:100%;max-width:280px}
@media screen and (max-width: 600px){.iqbr-button--w280{max-width:100% !important}}
.iqbr-button--butt{background-size:cover;background-color:#f50;font-size:18px !important;font-weight:700 !important;border-radius:12px !important;text-transform:none;font-family:Helvetica !important;height:auto}
.iqbr-button--butt-link{font-size:18px;line-height:27px;font-weight:700;text-transform:none;text-decoration:none;color:#f9f9f9;display:block;padding:16px 0 16px;text-align:center;letter-spacing:0px}
.iqbr-button--pb0{padding-bottom:0 !important}
